#!/usr/bin/env python3
import hashlib, html, json, runpy, time
from pathlib import Path
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260829_1000.py')),run_name='recipe_base')
TITLE='Carne Moída com Abóbora para Bebê: Refeição Macia e Fácil'; SLUG_KEY='carne-moida-abobora-bebe'; CLUSTER='Cluster 4 — Refeições com frango, carne e peixe'; KEYWORD='carne moída com abóbora para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']
def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Carne moída cozida com abóbora até ficar macia e úmida, com textura adaptável às habilidades da criança.','recipeCategory':'Almoço e jantar','recipeCuisine':'Brasileira','keywords':KEYWORD+', alimentação complementar, carne moída, abóbora','recipeYield':'4 porções pequenas','recipeIngredient':['200 g de carne bovina moída','1 xícara de abóbora descascada em cubos pequenos','2 colheres (sopa) de cebola bem picada','Água em pequena quantidade, se necessário para o cozimento'],'recipeInstructions':[{'@type':'HowToStep','text':'Cozinhe a cebola e a carne moída, desfazendo bem os grumos, até não haver partes cruas.'},{'@type':'HowToStep','text':'Junte a abóbora e um pouco de água, tampe e cozinhe até ficar muito macia.'},{'@type':'HowToStep','text':'Amasse parte da abóbora com o garfo e misture à carne para obter uma preparação úmida.'},{'@type':'HowToStep','text':'Espere amornar e adapte a textura às habilidades da criança antes de servir.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Esta carne moída com abóbora é uma opção simples para variar o almoço ou jantar. A abóbora cozinha junto da carne e pode ser parcialmente amassada no final, deixando a preparação úmida e fácil de adaptar.</p><p><strong>Atenção:</strong> adapte tamanho e textura às habilidades da criança e ofereça sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação ou deglutição e necessidades especiais exigem avaliação profissional individualizada.</p><h2>Ingredientes</h2><ul><li>200 g de carne bovina moída</li><li>1 xícara de abóbora descascada em cubos pequenos</li><li>2 colheres (sopa) de cebola bem picada</li><li>Água em pequena quantidade, se necessário para o cozimento</li></ul><h2>Modo de preparo</h2><ol><li>Coloque a cebola e a carne moída em uma panela e cozinhe, mexendo e desfazendo bem os grumos.</li><li>Quando a carne estiver sem partes cruas, acrescente a abóbora.</li><li>Adicione apenas a água necessária para ajudar o cozimento, tampe e mantenha em fogo baixo até a abóbora ficar bem macia.</li><li>Amasse parte da abóbora com o garfo e misture à carne. Se necessário, desfaça ainda mais os pedaços para adequar a textura.</li><li>Espere amornar antes de servir.</li></ol><h2>Como deve ficar a textura</h2><p>A abóbora deve ceder facilmente ao garfo e a carne precisa estar completamente cozida e bem desmanchada, sem grandes blocos compactados. Ao misturar a abóbora amassada, a preparação fica úmida sem precisar virar um purê totalmente liso.</p><h2>Como servir e adaptar</h2><p>Sirva a preparação em consistência compatível com as habilidades da criança. No início da alimentação complementar, o Ministério da Saúde orienta oferecer comida amassada e evoluir gradualmente a consistência, em vez de manter sempre preparações liquidificadas.</p><h2>Substituições culinárias</h2><p>Outros tipos de abóbora podem ser usados, desde que cozinhem até ficar macios. A cebola pode ser combinada com temperos naturais usados pela família. Para alergias ou necessidades alimentares específicas, procure um profissional habilitado em vez de fazer substituições clínicas por conta própria.</p><h2>Armazenamento</h2><p>Use utensílios limpos, mantenha a carne refrigerada antes do preparo e cozinhe-a completamente. Não guarde novamente a porção que já teve contato com a boca da criança ou com utensílio usado durante a refeição. Para conservação de sobras, siga as orientações oficiais de higiene, refrigeração e segurança alimentar adequadas ao seu equipamento.</p><h2>Perguntas frequentes</h2><h3>Precisa bater no liquidificador?</h3><p>Não. A abóbora bem cozida pode ser amassada com o garfo e a carne pode ser desmanchada durante o cozimento. A textura deve evoluir conforme as habilidades da criança.</p><h3>Posso deixar a receita mais úmida?</h3><p>Sim. Use um pouco da própria água do cozimento e amasse mais abóbora na mistura, sem transformar a preparação em líquido.</p><h3>Como saber se a carne está pronta?</h3><p>Ela deve estar completamente cozida, sem partes cruas, e bem separada em pedaços pequenos. A abóbora deve estar macia o suficiente para ser facilmente esmagada com o garfo.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/arroz-cremoso-com-frango-e-legumes-para.html'>Arroz Cremoso com Frango e Legumes para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/almondega-assada-de-frango-com.html'>Almôndega Assada de Frango com Abobrinha para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/almondegas-de-carne-moida-com-legumes.html'>Almôndegas de Carne Moída com Legumes para Bebês</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/composicao/saps/promocao-da-saude/guias-alimentares/publicacoes/guia_da_crianca_2019.pdf/view' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><h2>Conclusão</h2><p>A carne moída com abóbora amplia o cluster de refeições com uma preparação de panela e textura úmida, diferente das opções assadas e do arroz cremoso já publicados.</p><script type='application/ld+json'>{sj}</script>"""
def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('carne moída' in t and 'abóbora' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for beef pumpkin recipe'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists():
  original=base['TITLE']; base['TITLE']=TITLE
  try: base['generate_cover'](cp)
  finally: base['TITLE']=original
  base['git_commit_push']([cp],'Add unique AI food photo for beef pumpkin recipe'); time.sleep(8)
 content=article(cu)
 if MARKER not in content or cu not in content: raise RuntimeError('cover verification failed before publish')
 created=base['api'](tok,'POST',f'/blogs/{BLOG_ID}/posts',{'isDraft':'false','fetchBody':'true'},{'kind':'blogger#post','blog':{'id':BLOG_ID},'title':TITLE,'content':content,'labels':['Alimentação complementar','Almoço','Jantar','Carne','Abóbora']}); pid=str(created.get('id','')); url=created.get('url','')
 if not pid: raise RuntimeError('Blogger did not return post id')
 vc=(base['api'](tok,'GET',f'/blogs/{BLOG_ID}/posts/{pid}',{'view':'ADMIN'}).get('content') or '')
 if MARKER not in vc or cu not in vc: raise RuntimeError('published post failed marker/cover verification')
 log=base['load_log'](); log.append({'published_at':created.get('published',''),'title':TITLE,'url':url,'post_id':pid,'cluster':CLUSTER,'keyword':KEYWORD,'cover_url':cu,'marker':MARKER}); LOG_PATH.write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); RESULT_PATH.write_text(f'outcome=success\ntitle={TITLE}\nurl={url}\npost_id={pid}\ncluster={CLUSTER}\ncover_url={cu}\nmarker_verified=true\n',encoding='utf-8'); base['git_commit_push']([LOG_PATH,RESULT_PATH],'Record published beef pumpkin recipe')
if __name__=='__main__': main()
